import React, { useState, useRef } from 'react';
import './file_attachment.css';

const FileAttachment = ({ file }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const mediaRefs = useRef([]);

    const renderMedia = (f, index) => {
        const mediaProps = {
            style: {
                width: '100%',
                height: 'auto',
                maxWidth: '100%',
                display: 'block'
            },
            className: 'file_media',
            ref: el => {
                mediaRefs.current[index] = el;
            }
        };

        if (f.type.startsWith('image/')) {
            return (
                <img
                    {...mediaProps}
                    src={f.url}
                    alt={f.name}
                    onError={(e) => {
                        e.target.src = 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMjAwIiBoZWlnaHQ9IjIwMCIgdmlld0JveD0iMCAwIDIwMCAyMDAiIGZpbGw9Im5vbmUiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+CjxyZWN0IHdpZHRoPSIyMDAiIGhlaWdodD0iMjAwIiBmaWxsPSIjRjNGNEY2Ii8+CjxyZWN0IHg9Ijc1IiB5PSI3NSIgd2lkdGg9IjUwIiBoZWlnaHQ9IjUwIiBmaWxsPSIjOUNBM0JCIi8+Cjwvc3ZnPg==';
                    }}
                />
            );
        } else if (f.type.startsWith('video/')) {
            return (
                <div className="video_container">
                    <video
                        {...mediaProps}
                        src={f.url}
                        playsInline
                        controls
                        preload="metadata"
                    >
                        Your browser does not support the video tag.
                    </video>
                </div>
            );
        }

        return <div>Unsupported file</div>;
    };

    if (!file || file.length === 0) {
        return null;
    }

    return (
        <div className="file_attachment_wrapper">
            <div className="file_attachment">
                <div className="carousel_container" style={{ transform: `translateX(-${currentIndex * 100}%)` }}>
                    {file.map((f, index) => (
                        <div key={index} className="carousel_item">
                            {renderMedia(f, index)}
                        </div>
                    ))}
                </div>
            </div>

            {file.length > 1 && (
                <div className="carousel_indicators">
                    {file.map((_, index) => (
                        <span
                            key={index}
                            className={`indicator ${index === currentIndex ? 'active' : ''}`}
                            onClick={() => setCurrentIndex(index)}
                        ></span>
                    ))}
                </div>
            )}
        </div>
    );
};

export default FileAttachment;